import zen from 'zen';

/** @type {Handler} **/
export const handler = async (input) => {

  // Parámetros de regla
  const parameterBillingItemCodeForAmount = input?.parametros_de_la_regla?.parameter_billingItem_code_for_amount ?? null;
  const billingItemCode = input?.parametros_de_la_regla?.parameter_billingItem_code ?? null;

  // 1 Buscar importe base desde billing_items (ej: "consumo")
  const activeEnergyBillingItems = input?.tsl_wo_work_order_attribute?.billing_items?.active_energy_billing_items ?? [];
  const billingItemForAmount = activeEnergyBillingItems.find(item => item.legacy_billing_item_id === parameterBillingItemCodeForAmount);

  if (!billingItemForAmount) {
    return {
      ...input,
      result: {
        rule_description: `The parameter_billingItem_code_for_amount '${parameterBillingItemCodeForAmount}' could not be found in active_energy_billing_items`,
        status: 'ERROR',
      }
    };
  }

  const rawAmount = billingItemForAmount.billing_item_amount;
  const active_energy_amount = Number(rawAmount);
  if (isNaN(active_energy_amount)) {
    return {
      ...input,
      result: {
        rule_description: `Invalid active_energy_amount value: ${rawAmount}`,
        status: 'ERROR',
      }
    };
  }

  // 2 Consumo total
  const rawConsumption = input?.tsl_wo_work_order_attribute?.active_energy_consumption;
  const active_energy_consumption = Number(rawConsumption);
  if (isNaN(active_energy_consumption)) {
    return {
      ...input,
      result: {
        rule_description: `Invalid active_energy_consumption value: ${rawConsumption}`,
        status: 'ERROR',
      }
    };
  }

  // 3 Constante (percentage_rate)
  const rawConstant = input?.percentage_pricing?.percentage_rate;
  if (rawConstant === undefined || rawConstant === null || String(rawConstant).trim() === "") {
    return {
      ...input,
      result: {
        rule_description: 'constant_module_value (percentage_rate) is missing or empty',
        status: 'ERROR',
      }
    };
  }
  const constant_module_value = Number(rawConstant);
  if (isNaN(constant_module_value)) {
    return {
      ...input,
      result: {
        rule_description: `Invalid constant_module_value (not a number): ${rawConstant}`,
        status: 'ERROR',
      }
    };
  }

  // 4 Precios (desde custom_graduated_pricing_with_percentage)
  const prices = Array.isArray(input?.custom_graduated_pricing_with_percentage?.prices)
    ? input.custom_graduated_pricing_with_percentage.prices
    : [];
  if (prices.length === 0) {
    return {
      ...input,
      result: {
        rule_description: 'No prices found in custom_graduated_pricing_with_percentage.prices',
        status: 'ERROR',
      }
    };
  }

  const filteredRanges = prices
    .filter(r => r.code === billingItemCode)
    .sort((a, b) => Number(a.interval_high ?? 0) - Number(b.interval_high ?? 0))
    .map(r => ({
      limite: Number(r.interval_high) === 999999999 || r.interval_high == null ? 999999999 : Number(r.interval_high),
      precio: Number(r.base_price),
      porcentaje: (() => {
        const num = Number(r.percentage);
        return isNaN(num) ? NaN : (num > 1 ? num / 100 : num);
      })()
    }));

  if (filteredRanges.length === 0) {
    return {
      ...input,
      result: {
        rule_description: `No matching prices found for billingItemCode '${billingItemCode}'`,
        status: 'ERROR',
      }
    };
  }

  // 5 Seleccionar rango según importe
  let limite_anterior = 0;
  let i = 0;
  for (; i < filteredRanges.length; i++) {
    const rango = filteredRanges[i];
    if (
      (active_energy_amount >= limite_anterior && active_energy_amount <= rango.limite && rango.limite !== 999999999) ||
      (active_energy_amount >= limite_anterior && rango.limite === 999999999)
    ) {
      break;
    }
    limite_anterior = rango.limite;
  }
  if (i >= filteredRanges.length) i = filteredRanges.length - 1;
  const rangoSeleccionado = filteredRanges[i];

  // 6 Aplicar la fórmula
  let importe_alumbrado = 0;
  if (
    (active_energy_consumption <= constant_module_value) ||
    (rangoSeleccionado.precio > active_energy_amount * rangoSeleccionado.porcentaje)
  ) {
    importe_alumbrado = rangoSeleccionado.precio;
  } else {
    importe_alumbrado = active_energy_amount * rangoSeleccionado.porcentaje;
  }
  //Asignar el importe 
  const billingItems = input.tsl_wo_work_order_attribute.billing_items.public_lighting_billing_items;
  const billingItem = billingItems.find(item => item.legacy_billing_item_id === billingItemCode);

  if (!billingItem) {
    return {
      ...input,
        result: {
          rule_description: 'The parameter_billingItem_code ' + billingItemCode + ' could not be found in the billing concepts structure',
          status: 'ERROR',
        }
    };
  }
  billingItem.billing_item_amount = importe_alumbrado;

  // 8 Retorno
  return {
    ...input,
    result: {
      total_amount: importe_alumbrado,
      status: 'OK',
      rule_description: 'Public lighting amount calculation rule completed',
    },
  };
};
